def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opps = []
    prev_bids = []
    rich_aggressive = 0
    weak_opps = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                weak_opps += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 145 and opp.get('budget', 0) >= 120:
                    rich_aggressive += 1

    if budget <= 0:
        return 0.0

    if not alive_opps:
        return float(min(budget, 20.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    high_supply = supply >= 22
    low_supply = supply <= 17

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 1

    base = 0.0

    if danger >= 5:
        base = 0.96 * DAILY_SALARY
    elif danger >= 3:
        base = 0.82 * DAILY_SALARY
    elif low_supply and highest_prev < 120:
        base = 0.74 * DAILY_SALARY
    elif high_supply:
        base = 0.33 * DAILY_SALARY
    else:
        base = 0.48 * DAILY_SALARY

    if highest_prev >= 150:
        if danger <= 1 and high_supply:
            base = min(base, 0.26 * DAILY_SALARY)
        elif danger <= 2:
            base = min(base, 0.40 * DAILY_SALARY)
    elif highest_prev <= 95 and low_supply:
        base = max(base, 0.68 * DAILY_SALARY)
    elif avg_prev <= 110 and not high_supply:
        base = max(base, 0.58 * DAILY_SALARY)

    if rich_aggressive >= 2 and danger <= 2:
        base *= 0.82

    if weak_opps >= 2 and danger <= 1:
        base *= 0.9

    base += 8.0 * supply_pressure

    if day >= 8:
        if hp >= 6 and budget < 140:
            base *= 0.9
        elif danger >= 3:
            base *= 1.08

    reserve_floor = 0.0
    if hp > 4 and day <= 7:
        reserve_floor = 35.0

    bid = min(float(budget), base)
    if budget - bid < reserve_floor and danger <= 2:
        bid = max(0.0, budget - reserve_floor)

    if danger >= 5:
        bid = max(bid, min(float(budget), 64.0))
    elif danger >= 3:
        bid = max(bid, min(float(budget), 54.0))

    if bid > budget:
        bid = float(budget)
    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return float(min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids (immediate reaction only)
    prev_bids = []
    prev_by_id = {}
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                fb = float(b)
                prev_bids.append(fb)
                prev_by_id[oid] = fb
            except Exception:
                pass

    # Baseline bid depends on my urgency
    if my_hp <= 2 or my_no_water_days >= 2:
        urgency_factor = 0.95
    elif my_hp <= 4 or my_no_water_days >= 1:
        urgency_factor = 0.75
    else:
        urgency_factor = 0.6

    # Opponent pressure from yesterday
    if prev_bids:
        max_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))

        # Cindy-like aggressiveness: if someone bid very high yesterday, we shade up but not fully match
        if max_prev >= DAILY_SALARY * 1.55:  # ~139.5
            # Increase to just above likely clearing level
            target = max(avg_prev * 0.9, DAILY_SALARY * 0.68)
        elif max_prev >= DAILY_SALARY * 1.15:  # ~103.5
            target = max(avg_prev * 0.85, DAILY_SALARY * 0.6)
        else:
            target = max(avg_prev * 0.75, DAILY_SALARY * 0.5)
    else:
        target = DAILY_SALARY * 0.55

    target *= urgency_factor

    # Budget-aware and supply-aware caps
    # If supply is low, water is scarce: bid relatively higher.
    scarcity = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity = (MAX_SUPPLY - min(MAX_SUPPLY, max(MIN_SUPPLY, supply))) / float(MAX_SUPPLY - MIN_SUPPLY)
    else:
        scarcity = 0.5

    # Add scarcity adjustment without exceeding salary too much
    target *= (1.0 + 0.25 * scarcity)

    # Ensure we don't overspend: keep a reserve for later days
    # Episode is 10 days; earlier days can spend more, later days should conserve.
    # day is 0-indexed or 1-indexed unknown; use a gentle curve.
    day_weight = 1.0
    if day >= 7:
        day_weight = 0.75
    elif day >= 5:
        day_weight = 0.85
    elif day <= 2:
        day_weight = 1.05

    target *= day_weight

    # Hard caps to avoid bankruptcy
    max_reasonable = DAILY_SALARY * 1.25
    bid = min(target, max_reasonable, my_budget)

    # If my budget is low, still bid enough to avoid death if very urgent
    if my_hp <= 2:
        bid = min(my_budget, max(bid, DAILY_SALARY * 0.85))

    # Final clamp
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    base_bid = DAILY_SALARY * 0.7

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    bid = base_bid

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 5:
                bid = max(base_bid, DAILY_SALARY * 0.75)
            else:
                bid = max(base_bid, DAILY_SALARY * 0.95)
        else:
            bid = max(base_bid, highest_prev_bid + 5.0)

    if my_status['hp'] <= 3:
        bid = max(bid, DAILY_SALARY * 0.98)
    elif my_status['hp'] <= 6:
        bid = max(bid, DAILY_SALARY * 0.85)

    current_day = day_context['day']
    if current_day >= EPISODE_DAYS - 1:
        bid = max(bid, DAILY_SALARY * 0.99)
    elif current_day >= EPISODE_DAYS - 3:
        bid = max(bid, DAILY_SALARY * 0.95)

    final_bid = min(my_status['budget'], bid)

    if my_status['budget'] >= DAILY_SALARY * 0.3 and final_bid < DAILY_SALARY * 0.3:
        final_bid = min(my_status['budget'], DAILY_SALARY * 0.3)

    final_bid = max(0.0, final_bid)

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    SUPPLY = day_context['supply']
    DAY = day_context['day']
    HP = my_status['hp']
    BUDGET = my_status['budget']
    NO_WATER_DAYS = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    n_alive = len(alive_opponents)

    # Estimate number of water units available today
    water_units = int(SUPPLY // WATER_REQ)
    total_players_alive = n_alive + 1  # including self
    # If enough water for everyone, bid low
    if water_units >= total_players_alive:
        base_bid = DAILY_SALARY * 0.3
    else:
        base_bid = DAILY_SALARY * 0.5

    # Adjust based on previous opponent traces
    highest_prev_bid = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            highest_prev_bid = max(highest_prev_bid, prev['bid'])

    # If someone was aggressive yesterday, be cautious
    if highest_prev_bid > DAILY_SALARY * 0.8:
        if HP <= 2:
            base_bid = max(base_bid, DAILY_SALARY * 0.8)
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.4)
    else:
        if HP <= 2:
            base_bid = max(base_bid, DAILY_SALARY * 0.7)

    # Ensure bid is at least minimal to survive if very low HP
    if HP <= 1 and NO_WATER_DAYS >= 1:
        base_bid = DAILY_SALARY * 0.9

    # Cap by budget
    bid = min(BUDGET, base_bid)
    return float(bid)
